export function t(lang,key,values={}){
  const value=sharedCopy[lang]?.[key] ?? sharedCopy.en[key] ?? sharedCopy.ru[key] ?? key;
  return String(value).replace(/\{(\w+)\}/g,(_,name)=>values[name] ?? '');
}
