export function localizeGiveawayDom(root,lang){
  if(lang==='ru'||!root)return;
  const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);
  const nodes=[];while(walker.nextNode())nodes.push(walker.currentNode);
  for(const node of nodes){for(const [source,key] of Object.entries(giveawayRussianText)){if(node.nodeValue.includes(source))node.nodeValue=node.nodeValue.replaceAll(source,t(lang,key));}}
}
