const roleInfo=(account,lang='ru')=>{
  const fallback=account?.is_superadmin?'superadmin':account?.is_manager?'manager':account?.is_agent?'agent':account?'user':'guest';
  const role=account?.display_role||fallback;
  const ru={superadmin:'Владелец',manager:'Менеджер',agent:'Агент',user:'Пользователь',guest:'Гость'};
  const en={superadmin:'Owner',manager:'Manager',agent:'Agent',user:'User',guest:'Guest'};
  const regional={tg:{superadmin:'Соҳиб',manager:'Менеҷер',agent:'Агент',user:'Корбар',guest:'Меҳмон'},uz:{superadmin:'Egasi',manager:'Menejer',agent:'Agent',user:'Foydalanuvchi',guest:'Mehmon'},tk:{superadmin:'Eýesi',manager:'Menejer',agent:'Agent',user:'Ulanyjy',guest:'Myhman'},ky:{superadmin:'Ээси',manager:'Менеджер',agent:'Агент',user:'Колдонуучу',guest:'Конок'},kk:{superadmin:'Иесі',manager:'Менеджер',agent:'Агент',user:'Пайдаланушы',guest:'Қонақ'},tr:{superadmin:'Sahip',manager:'Yönetici',agent:'Acente',user:'Kullanıcı',guest:'Misafir'},az:{superadmin:'Sahib',manager:'Menecer',agent:'Agent',user:'İstifadəçi',guest:'Qonaq'}};
  const identity={superadmin:'★ ВЛАДЕЛЕЦ',manager:'⚑ МЕНЕДЖЕР',agent:'✓ АГЕНТ',user:'PARTNERS MEMBER',guest:'PARTNERS MEMBER'};
  const labels=lang==='ru'?ru:(regional[lang]||en);
  return {role,label:labels[role]||labels.user,identity:identity[role]||identity.user};
};
